import math


def area_resistente(d, p):
    return math.pi / 4 * (d - 0.9382 * p) ** 2


def precarico(T, d, K=0.2):
    return T / (K * d)

import pint

u = pint.UnitRegistry()


def tensione_bullone(Fi, P, C, As):
    return ((Fi + C * P) / As).to(u.MPa)

from uncertainties import ufloat


def precarico_incerto(T, d, K, uK):
    return T / (ufloat(K, uK) * d)
